content:
:root {
  --bg-primary: #f8fafc;
  --bg-surface: #ffffff;
  --bg-hover: #f1f5f9;
  --text-main: #0f172a;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --primary-color: #3b82f6;
  --primary-hover: #2563eb;
  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.05), 0 1px 2px rgba(0, 0, 0, 0.03);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.07), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-primary);
  color: var(--text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

/* アプリケーション全体レイアウト */
.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 32px 20px 48px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

/* ヘッダーエリア */
.header {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.title {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-main);
  letter-spacing: -0.02em;
}

.subtitle {
  font-size: 0.95rem;
  color: var(--text-muted);
}

/* 操作パネル（期間フィルター & 店舗切り替え） */
.controls-panel {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  background-color: var(--bg-surface);
  padding: 16px 20px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
  box-shadow: var(--shadow-sm);
}

.filter-group {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.filter-label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-muted);
  margin-right: 4px;
}

.filter-btn {
  background-color: #f8fafc;
  color: var(--text-muted);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  padding: 6px 14px;
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
}

.filter-btn:focus-visible {
  outline: 2px solid var(--primary-color);
  outline-offset: 2px;
}

.filter-btn:hover {
  background-color: var(--bg-hover);
  color: var(--text-main);
}

.filter-btn-active {
  background-color: var(--primary-color);
  color: #ffffff;
  border-color: var(--primary-color);
  font-weight: 600;
}

.filter-btn-active:hover {
  background-color: var(--primary-hover);
  color: #ffffff;
}

.store-toggles {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.toggle-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: 9999px;
  padding: 6px 14px;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-main);
  cursor: pointer;
  transition: all 0.2s ease;
  user-select: none;
}

.toggle-btn:focus-visible {
  outline: 2px solid var(--primary-color);
  outline-offset: 2px;
}

.toggle-btn:hover:not(:disabled) {
  background-color: var(--bg-hover);
}

.toggle-btn:disabled,
.toggle-btn[aria-disabled='true'] {
  cursor: not-allowed;
}

.toggle-btn[aria-pressed='false'],
.toggle-btn-inactive {
  opacity: 0.5;
  border-color: var(--border-color);
}

.toggle-btn[aria-pressed='true'],
.toggle-btn-active {
  opacity: 1;
  border-color: var(--store-color, var(--primary-color));
}

.toggle-btn[aria-pressed='false'] .toggle-dot,
.toggle-btn-inactive .toggle-dot {
  opacity: 0.3;
}

.toggle-btn[aria-pressed='true'] .toggle-dot,
.toggle-btn-active .toggle-dot {
  opacity: 1;
}

.toggle-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  display: inline-block;
  flex-shrink: 0;
  background-color: var(--store-color, currentColor);
  opacity: var(--store-opacity, 1);
  transition: opacity 0.2s ease;
}

/* サマリーカード一覧 */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 16px;
}

.stat-card {
  background-color: var(--bg-surface);
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
  border-left: 4px solid var(--store-accent-color, var(--store-color, transparent));
  padding: 20px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 14px;
  transition: transform 0.2s ease, box-shadow 0.2s ease, opacity 0.2s ease;
}

.stat-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.stat-card[aria-pressed='false'],
.stat-card[data-active='false'],
.stat-card-inactive {
  opacity: 0.45;
}

.stat-card[aria-pressed='true'],
.stat-card[data-active='true'],
.stat-card-active {
  opacity: 1;
}

.stat-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid #f1f5f9;
  padding-bottom: 10px;
}

.stat-name {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--text-main);
}

.stat-badge {
  font-size: 0.75rem;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 9999px;
  background-color: #f1f5f9;
  color: var(--text-muted);
}

.stat-values {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.stat-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
}

.stat-label {
  font-size: 0.875rem;
  color: var(--text-muted);
}

.stat-num {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--text-main);
  font-variant-numeric: tabular-nums;
}

/* グラフカード */
.chart-card {
  background-color: var(--bg-surface);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border-color);
  padding: 24px 20px 20px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.unit-note {
  font-size: 0.8125rem;
  color: var(--text-muted);
  text-align: right;
  margin-bottom: 4px;
}

.chart-wrapper {
  width: 100%;
  height: 420px;
  min-height: 320px;
}

/* カスタムツールチップ */
.custom-tooltip {
  background-color: rgba(255, 255, 255, 0.96);
  backdrop-filter: blur(4px);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 12px 14px;
  box-shadow: var(--shadow-lg);
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 160px;
  z-index: 100;
}

.tooltip-title {
  font-size: 0.875rem;
  font-weight: 700;
  color: var(--text-main);
  border-bottom: 1px solid #f1f5f9;
  padding-bottom: 4px;
}

.tooltip-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  font-size: 0.8125rem;
}

.tooltip-label {
  color: var(--text-muted);
  display: flex;
  align-items: center;
  gap: 6px;
}

.tooltip-val {
  font-weight: 700;
  color: var(--text-main);
  font-variant-numeric: tabular-nums;
}

/* レスポンシブ対応 */
@media (max-width: 768px) {
  .app-container {
    padding: 20px 12px 36px;
    gap: 16px;
  }

  .title {
    font-size: 1.4rem;
  }

  .controls-panel {
    flex-direction: column;
    align-items: stretch;
    gap: 12px;
    padding: 14px;
  }

  .filter-group {
    justify-content: flex-start;
  }

  .store-toggles {
    justify-content: flex-start;
  }

  .chart-card {
    padding: 16px 10px 12px;
  }

  .chart-wrapper {
    height: 320px;
  }
}

export type StoreKey = 'shibuya' | 'shinjuku' | 'ikebukuro';

export type ActiveStoresState = Record<StoreKey, boolean>;

export interface MonthlyVisitorData {
  month: string;
  shibuya: number;
  shinjuku: number;
  ikebukuro: number;
}

export interface StoreMeta {
  id: StoreKey;
  name: string;
  color: string;
}

export type FilterPeriod = 'all' | 'firstHalf' | 'secondHalf';

export interface StoreStats {
  key: StoreKey;
  name: string;
  total: number;
  average: number;
  maxMonth: string;
  maxValue: number;
  color: string;
}

export interface CustomTooltipPayload {
  name: string;
  value: number;
  color: string;
  dataKey: string;
}

export interface CustomTooltipProps {
  active?: boolean;
  payload?: CustomTooltipPayload[];
  label?: string;
}

import React from 'react';
import { StoreStats, StoreKey } from '../types';

interface StatsSummaryProps {
  stats?: StoreStats[];
  activeStores?: Record<StoreKey, boolean>;
  onToggleStore?: (key: StoreKey) => void;
}

export default function StatsSummary({
  stats = [],
  activeStores = { shibuya: true, shinjuku: true, ikebukuro: true },
  onToggleStore
}: StatsSummaryProps) {
  if (stats.length === 0) {
    return (
      <div className="stats-grid">
        <div className="stat-card" style={{ textAlign: 'center', gridColumn: '1 / -1' }}>
          <p className="stat-label">対象データがありません</p>
        </div>
      </div>
    );
  }

  return (
    <div className="stats-grid">
      {stats.map((stat) => {
        const isStoreActive = activeStores[stat.key] ?? true;
        const cardStyle: React.CSSProperties = {
          '--store-color': stat.color,
          cursor: onToggleStore ? 'pointer' : 'default'
        } as React.CSSProperties;

        const handleClick = () => {
          onToggleStore?.(stat.key);
        };

        const handleKeyDown = (e: React.KeyboardEvent) => {
          if (onToggleStore && (e.key === 'Enter' || e.key === ' ')) {
            e.preventDefault();
            onToggleStore(stat.key);
          }
        };

        const cardClassName = isStoreActive ? 'stat-card' : 'stat-card stat-card-inactive';

        return (
          <div
            key={stat.key}
            className={cardClassName}
            style={cardStyle}
            data-active={isStoreActive}
            onClick={handleClick}
            onKeyDown={handleKeyDown}
            role={onToggleStore ? 'button' : undefined}
            tabIndex={onToggleStore ? 0 : undefined}
            aria-pressed={onToggleStore ? isStoreActive : undefined}
          >
            <div className="stat-header">
              <span className="stat-name">{stat.name}</span>
              <span className="stat-badge">
                {isStoreActive ? '表示中' : '非表示'}
              </span>
            </div>
            <div className="stat-values">
              <div className="stat-row">
                <span className="stat-label">期間合計来客数</span>
                <span className="stat-num">{stat.total.toLocaleString()} 人</span>
              </div>
              <div className="stat-row">
                <span className="stat-label">月平均来客数</span>
                <span className="stat-num">{stat.average.toLocaleString()} 人</span>
              </div>
              <div className="stat-row">
                <span className="stat-label">最多来客月</span>
                <span className="stat-num">
                  {stat.maxMonth} ({stat.maxValue.toLocaleString()} 人)
                </span>
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

import React from 'react';
import { FilterPeriod, StoreKey, StoreMeta } from '../types';

interface ChartControlsProps {
  period: FilterPeriod;
  onPeriodChange: (p: FilterPeriod) => void;
  stores?: StoreMeta[];
  activeStores?: Record<StoreKey, boolean>;
  onToggleStore?: (key: StoreKey) => void;
  isDisableToggle?: boolean;
}

export default function ChartControls({
  period,
  onPeriodChange,
  stores = [],
  activeStores = { shibuya: true, shinjuku: true, ikebukuro: true },
  onToggleStore,
  isDisableToggle = false
}: ChartControlsProps) {
  const periods: { key: FilterPeriod; label: string }[] = [
    { key: 'all', label: '通年 (1〜12月)' },
    { key: 'firstHalf', label: '上半期 (1〜6月)' },
    { key: 'secondHalf', label: '下半期 (7〜12月)' }
  ];

  const activeCount = stores.reduce(
    (count, store) => (activeStores[store.id] ? count + 1 : count),
    0
  );

  const handlePeriodClick = (selectedPeriod: FilterPeriod) => {
    onPeriodChange?.(selectedPeriod);
  };

  const handleToggleClick = (storeId: StoreKey) => {
    onToggleStore?.(storeId);
  };

  return (
    <div className="controls-panel">
      <div className="filter-group">
        <span className="filter-label">表示期間:</span>
        {periods.map((p) => {
          const isActive = period === p.key;
          const buttonClass = isActive ? 'filter-btn filter-btn-active' : 'filter-btn';
          return (
            <button
              key={p.key}
              type="button"
              className={buttonClass}
              onClick={() => handlePeriodClick(p.key)}
            >
              {p.label}
            </button>
          );
        })}
      </div>

      <div className="store-toggles">
        <span className="filter-label">店舗絞り込み:</span>
        {stores.map((store) => {
          const isActive = activeStores[store.id] ?? false;
          const isLastActive = isActive && activeCount <= 1;
          const isDisabled = isDisableToggle || isLastActive;

          const buttonStyle: React.CSSProperties = {
            '--store-color': store.color,
            borderColor: isActive ? 'var(--store-color)' : undefined,
            opacity: isActive ? 1 : 0.5,
            cursor: isDisabled ? 'not-allowed' : 'pointer'
          } as React.CSSProperties;

          return (
            <button
              key={store.id}
              type="button"
              className="toggle-btn"
              disabled={isDisabled}
              aria-pressed={isActive}
              aria-disabled={isDisabled}
              title={isLastActive ? '最低1つの店舗を表示する必要があります' : undefined}
              onClick={() => handleToggleClick(store.id)}
              style={buttonStyle}
            >
              <span
                className="toggle-dot"
                style={{
                  backgroundColor: 'var(--store-color)',
                  opacity: isActive ? 1 : 0.3
                }}
              />
              <span>{store.name}</span>
            </button>
          );
        })}
      </div>
    </div>
  );
}

import { useState, useMemo } from 'react';
import {
  ResponsiveContainer,
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend
} from 'recharts';
import { MonthlyVisitorData, StoreMeta, StoreKey, FilterPeriod, StoreStats } from './types';
import StatsSummary from './components/StatsSummary';
import ChartControls from './components/ChartControls';
import CustomChartTooltip from './components/CustomChartTooltip';
import './index.css';

const STORES: StoreMeta[] = [
  { id: 'shibuya', name: '渋谷店', color: '#3b82f6' },
  { id: 'shinjuku', name: '新宿店', color: '#10b981' },
  { id: 'ikebukuro', name: '池袋店', color: '#f59e0b' }
];

const INITIAL_VISITOR_DATA: MonthlyVisitorData[] = [
  { month: '1月', shibuya: 12400, shinjuku: 14800, ikebukuro: 10200 },
  { month: '2月', shibuya: 11800, shinjuku: 13900, ikebukuro: 9800 },
  { month: '3月', shibuya: 14500, shinjuku: 16200, ikebukuro: 11900 },
  { month: '4月', shibuya: 15800, shinjuku: 17100, ikebukuro: 12500 },
  { month: '5月', shibuya: 16900, shinjuku: 18400, ikebukuro: 13800 },
  { month: '6月', shibuya: 13600, shinjuku: 15300, ikebukuro: 11400 },
  { month: '7月', shibuya: 17200, shinjuku: 19100, ikebukuro: 14200 },
  { month: '8月', shibuya: 18900, shinjuku: 20500, ikebukuro: 15600 },
  { month: '9月', shibuya: 14800, shinjuku: 16400, ikebukuro: 12300 },
  { month: '10月', shibuya: 16200, shinjuku: 17900, ikebukuro: 13100 },
  { month: '11月', shibuya: 15500, shinjuku: 17200, ikebukuro: 12700 },
  { month: '12月', shibuya: 20100, shinjuku: 22800, ikebukuro: 16900 }
];

export default function App() {
  const [period, setPeriod] = useState<FilterPeriod>('all');
  const [activeStores, setActiveStores] = useState<Record<StoreKey, boolean>>({
    shibuya: true,
    shinjuku: true,
    ikebukuro: true
  });

  const handleToggleStore = (key: StoreKey) => {
    setActiveStores((prev) => {
      const activeCount = Object.values(prev).filter(Boolean).length;
      if (prev[key] && activeCount <= 1) {
        return prev;
      }
      return {
        ...prev,
        [key]: !prev[key]
      };
    });
  };

  const filteredData = useMemo(() => {
    if (period === 'firstHalf') {
      return INITIAL_VISITOR_DATA.slice(0, 6);
    }
    if (period === 'secondHalf') {
      return INITIAL_VISITOR_DATA.slice(6, 12);
    }
    return INITIAL_VISITOR_DATA;
  }, [period]);

  const stats = useMemo<StoreStats[]>(() => {
    return STORES.map((store) => {
      let total = 0;
      let maxValue = -Infinity;
      let maxMonth = '-';

      filteredData.forEach((d) => {
        const val = d[store.id];
        total += val;
        if (val > maxValue) {
          maxValue = val;
          maxMonth = d.month;
        }
      });

      const average = filteredData.length > 0 ? Math.round(total / filteredData.length) : 0;

      return {
        key: store.id,
        name: store.name,
        color: store.color,
        total,
        average,
        maxMonth,
        maxValue: maxValue === -Infinity ? 0 : maxValue
      };
    });
  }, [filteredData]);

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">主要店舗 月別来客数ダッシュボード</h1>
        <p className="subtitle">
          渋谷店・新宿店・池袋店の月別来客数の推移比較、期間ごとの実績サマリーを確認できます。
        </p>
      </header>

      <ChartControls
        period={period}
        onPeriodChange={setPeriod}
        stores={STORES}
        activeStores={activeStores}
        onToggleStore={handleToggleStore}
      />

      <StatsSummary
        stats={stats}
        activeStores={activeStores}
        onToggleStore={handleToggleStore}
      />

      <section className="chart-card">
        <div className="unit-note">単位: 来客数 (人)</div>
        <div className="chart-wrapper">
          <ResponsiveContainer width="100%" height="100%">
            <LineChart
              data={filteredData}
              margin={{ top: 20, right: 30, left: 10, bottom: 10 }}
            >
              <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" vertical={false} />
              <XAxis
                dataKey="month"
                stroke="#64748b"
                tick={{ fill: '#64748b', fontSize: 13 }}
                tickLine={false}
                axisLine={{ stroke: '#cbd5e1' }}
              />
              <YAxis
                stroke="#64748b"
                tick={{ fill: '#64748b', fontSize: 13 }}
                tickLine={false}
                axisLine={{ stroke: '#cbd5e1' }}
                tickFormatter={(value: number) => `${(value / 1000).toLocaleString()}千人`}
                domain={['auto', 'auto']}
              />
              <Tooltip content={<CustomChartTooltip />} />
              <Legend
                verticalAlign="top"
                align="right"
                wrapperStyle={{ paddingBottom: 16 }}
                iconType="circle"
              />
              {STORES.map((store) => {
                if (!activeStores[store.id]) return null;
                return (
                  <Line
                    key={store.id}
                    type="monotone"
                    dataKey={store.id}
                    name={store.name}
                    stroke={store.color}
                    strokeWidth={3}
                    dot={{ r: 4, strokeWidth: 2, fill: '#ffffff', stroke: store.color }}
                    activeDot={{ r: 7, strokeWidth: 0, fill: store.color }}
                    animationDuration={600}
                  />
                );
              })}
            </LineChart>
          </ResponsiveContainer>
        </div>
      </section>
    </div>
  );
}

import React from 'react';
import { CustomTooltipProps } from '../types';

export default function CustomChartTooltip({
  active = false,
  payload = [],
  label = ''
}: CustomTooltipProps) {
  if (active && payload && payload.length > 0) {
    return (
      <div className="custom-tooltip">
        <div className="tooltip-title">{label}</div>
        {payload.map((entry) => (
          <div key={entry.dataKey} className="tooltip-row">
            <span className="tooltip-label">
              <span
                style={{
                  display: 'inline-block',
                  width: 8,
                  height: 8,
                  borderRadius: '50%',
                  backgroundColor: entry.color
                }}
              />
              {entry.name}
            </span>
            <span className="tooltip-val">{entry.value.toLocaleString()} 人</span>
          </div>
        ))}
      </div>
    );
  }
  return null;
}
